{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/logo-cloud.json
    A heading and the names of customers or partners as Lucide glyphs with a name. Axes: layout (grid, row), columns (2, 3, 4), item (name, icon only, tile), density, tone.
    Props (p): id, title, logos, layout, cols, item, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_logos = ($p['logos'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '4')}
{var $v_item = ($p['item'] ?? 'name')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if ui_t(ui_eq($v_layout, 'row'))}
  {=ui_include('blocks/logo-ribbon.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'logos' => $v_logos, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel]])|noescape}
{else}
  {capture $c_4}
    {capture $c_3}
      {foreach ui_l($v_logos) as $v_logo}
        {capture $c_2}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_logo, ['icon'])), 'Size' => 24]])|noescape}
          {capture $c_1}
            {=ui_text(ui_get($v_logo, ['name']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold', 'Class' => ui_s((ui_t(ui_eq($v_item, 'icon')) ? 'sr-only' : ''))], 'children' => $c_1])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Justify' => 'center', 'Class' => ui_s(ui_cnv(['text-muted-foreground', (ui_t(ui_eq($v_item, 'tile')) ? 'flex-col rounded p-4 inset-ring inset-ring-border' : '')])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_2])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_cols, '2')) ? '2' : (ui_t(ui_eq($v_cols, '3')) ? '2-3' : (ui_t(ui_eq($v_cols, '4')) ? '2-4' : '3-6')))), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_3])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_4])|noescape}
{/if}
